using System;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Garnet.cluster;

namespace Garnet.cluster.Tests
{
    internal class MigrateSessionTests
    {
        [Fact]
        public async Task BeginAsyncMigrationTaskAsync_LogsError_WhenRelinquishOwnershipFails()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var clusterProviderMock = new Mock<ClusterProvider>(
                null!, // serverOptions
                null!, // loggerFactory
                null!, // migrationManager
                null!, // clusterManager
                null!  // storeWrapper
            );

            // We cannot instantiate MigrateSession directly because it is internal sealed,
            // so we create a partial class in the test project to expose the method for testing.
            // Here we assume such a partial class exists with an internal method InvokeBeginAsyncMigrationTaskAsync.

            var slots = new System.Collections.Generic.HashSet<int> { 1, 2, 3 };
            var migrateSession = MigrateSessionTestHelper.CreateMigrateSession(
                clusterProviderMock.Object,
                loggerMock.Object,
                "127.0.0.1",
                6379,
                "targetNodeId",
                "sourceNodeId",
                slots);

            // Setup mocks or internal state to simulate RelinquishOwnership failure.
            // Since we cannot override methods, we rely on the actual implementation or partial class helpers.

            // Act
            await migrateSession.InvokeBeginAsyncMigrationTaskAsync();

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Failed to relinquish ownership from source node")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.AtLeastOnce);
        }
    }

